var i=`0520-zereshk-polo-ba-morgh`;var n=`world-0520`;var a=`IR`;var r=`western-asia`;var o=4;var s=112;var d={en:`Zereshk Polo ba Morgh`,ua:`Зерешк-поло з куркою`};var g={en:`A traditional dish from Iran, centered on chicken thigh, yellow onion, tomato paste, basmati rice. A measured home-kitchen version organized by cooking step. Uses cranberries as a tart substitute for Iranian barberries, absent from the ingredient catalog.`,ua:`Традиційна страва кухні країни Іран. Основні складники: куряче стегно, жовта цибуля, томатна паста, рис басматі. Домашній варіант із кількостями продуктів за етапами приготування. Замість іранського барбарису, якого немає в каталозі, використано кислу журавлину.`};var l=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`chicken-thigh`,780,`g`],[`yellow-onion`,200,`g`],[`extra-virgin-olive-oil`,50,`ml`],[`ground-turmeric`,4,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 65 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 65 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:65,i:[[`water`,500,`ml`],[`tomato-paste`,65,`g`],[`ground-cardamom`,4,`g`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 30 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 30 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:30,i:[[`basmati-rice`,440,`g`],[`saffron-threads`,.4,`g`]]},{en:`Quickly sauté tart cranberries with butter, almonds and a little saffron, then scatter them over the rice and braised chicken.`,ua:`Швидко прогрійте кислу журавлину з маслом, мигдалем і шафраном, посипте рис і тушковану курятину.`,t:[`seasoning`,`garnishing`],m:5,i:[[`cranberry`,90,`g`],[`almond`,70,`g`],[`unsalted-butter`,35,`g`]]}];var u={slug:i,id:n,country:`IR`,region:r,servings:4,minutes:112,title:d,text:g,steps:l};export{a as country,u as default,n as id,s as minutes,r as region,o as servings,i as slug,l as steps,g as text,d as title};